// Extract incoming client inquiry & setup parameters
const incoming = $input.first().json;
const body = incoming.body || incoming;
const correlationId = body.correlationId || incoming.headers?.['x-correlation-id'] || `corr_gtools_${Date.now()}`;

const clientName = body.clientName || body.name || 'Private Sovereign Investor';
const email = body.email || 'privateadvisory@emanuelrendas.com';
const budgetAed = Number(body.budgetAed || body.propertyPriceAed || body.budget || 15000000);
const sqft = Number(body.unitSizeSqft || body.sqft || 1850);
const rentAed = Number(body.expectedAnnualRentAed || body.rent || Math.round(budgetAed * 0.078));
const serviceCharge = Number(body.serviceChargePerSqft || body.sc || 18);
const strategicFocus = body.strategicFocus || (budgetAed >= 10000000 ? 'sovereign_capital_preservation' : 'high_net_yield');
const projectName = body.projectName || (budgetAed >= 15000000 ? 'Como Residences' : 'Rosehill');

return [{
  json: {
    correlationId,
    clientName,
    email,
    budgetAed,
    sqft,
    rentAed,
    serviceCharge,
    strategicFocus,
    projectName,
    timestamp: new Date().toISOString()
  }
}];

